def t(title,content):return dict(type='text',title=title,content=content)
def warning(content):return dict(type='warning',title='Безопасность и пределы вывода',content=content)
def remember(content):return dict(type='remember',content=content)
def q(question,answers,correct,explanation):
    shift=sum(map(ord,question))%len(answers)
    return dict(type='question',question=question,answers=answers[shift:]+answers[:shift],correctAnswer=(correct-shift)%len(answers),explanation=explanation)
def c(question,value,unit,explanation,tolerance=.01):
    return dict(type='calculation',question=question,correctValue=value,tolerance=tolerance,unit=unit,
                hint='Проверьте единицы, число событий и условия модели.',explanation=explanation)
def scope():
    return dict(type='oscilloscope',title='P1-S • виртуальный пассивный сигнал',
                question='Для разности A−B получите размах 50–90% высоты без обрезания, меняя V/div. Это виртуальная модель, не инструкция подключения к автомобилю.',
                scenario='sine',exercise='voltageScale',initialSettings=dict(voltsPerDiv=5,millisecondsPerDiv=4,
                    centerVoltage=0,triggerLevel=0,edge='rising',mode='normal'))


